<?php
declare(strict_types=1);
namespace App\Http\Requests\Admin\Plans;
use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
final class StorePlanRequest extends FormRequest { public function authorize(): bool{return $this->user('admin')!==null;} protected function prepareForValidation():void{$this->merge(['code'=>strtoupper(trim((string)$this->input('code'))),'is_active'=>$this->boolean('is_active'),'domain_management_enabled'=>$this->boolean('domain_management_enabled'),'features'=>array_values(array_filter(preg_split('/\r\n|\r|\n/',(string)$this->input('features_text','')) ?: []))]);} public function rules():array{return ['name'=>['required','string','max:255'],'code'=>['required','max:50','regex:/^[A-Z][A-Z0-9_]*$/',Rule::unique('plans','code')],'plan_type'=>['required',Rule::in(['basic','professional','enterprise'])],'color'=>['required','string','max:30'],'description'=>['nullable','string','max:1000'],'price'=>['required','numeric','min:0'],'discount_percentage'=>['nullable','numeric','between:0,100'],'limits_mode'=>['required',Rule::in(['limited','unlimited'])],'included_users'=>['nullable','integer','min:1'],'properties_limit'=>['nullable','integer','min:1'],'storage_quota_gb'=>['nullable','integer','min:1'],'active_auctions_limit'=>['nullable','integer','min:1'],'subscription_billing_cycle'=>['required',Rule::in(['monthly','quarterly','yearly'])],'available_from'=>['nullable','date'],'features'=>['required','array','min:1'],'features.*'=>['string','max:255'],'is_active'=>['boolean'],'domain_management_enabled'=>['boolean']];} public function attributes():array{return ['name'=>'اسم الباقة','code'=>'رمز الباقة','price'=>'السعر','features'=>'مزايا الباقة'];}}
